// FCM push registration (real integration — requires FIREBASE_* dart-defines
// and platform files generated by `flutterfire configure` / manual setup).
// Without config the app still runs; tokens are simply not registered.
import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_messaging/firebase_messaging.dart';
import 'package:flutter/foundation.dart';

import 'api/api_client.dart';
import 'config.dart';

class PushServiceBootstrap {
  static Future<void> maybeInit() async {
    if (!AppConfig.pushConfigured) {
      debugPrint('[push] FIREBASE_* dart-defines missing — push registration skipped');
      return;
    }
    try {
      await Firebase.initializeApp(
        options: FirebaseOptions(
          apiKey: AppConfig.firebaseApiKey,
          appId: AppConfig.firebaseAppId,
          messagingSenderId: AppConfig.firebaseMessagingSenderId,
          projectId: AppConfig.firebaseProjectId,
        ),
      );
      final messaging = FirebaseMessaging.instance;
      final permission = await messaging.requestPermission(alert: true, badge: true, sound: true);
      if (permission.authorizationStatus == AuthorizationStatus.authorized) {
        final token = await messaging.getToken();
        if (token != null) {
          await ApiClient().post('/me/devices', data: {
            'platform': defaultTargetPlatform == TargetPlatform.iOS ? 'ios' : 'android',
            'push_token': token,
          });
        }
        messaging.onTokenRefresh.listen((t) async {
          await ApiClient().post('/me/devices', data: {
            'platform': defaultTargetPlatform == TargetPlatform.iOS ? 'ios' : 'android',
            'push_token': t,
          });
        });
      }
    } catch (e) {
      debugPrint('[push] init failed: $e');
    }
  }
}
